mapper.select:
SELECT d.declaration_id, d.declaration_no, d.student_name,
       u.user_name AS student_no,
       d.class_name, d.academic_year, d.semester,
       d.status, d.total_score
FROM assess_declaration d
LEFT JOIN sys_user u ON d.user_id = u.user_id

	d.del_flag = '0'

		AND u.dept_id = #{deptId}


		AND d.academic_year = #{academicYear}


		AND d.semester = #{semester}


		AND d.status = #{status}


		AND d.student_name like concat('%', #{studentName}, '%')


order by d.declaration_id desc
